"""Freshness is about every generated byte, independent of file timestamps."""

import os

import pytest

from m4l_builder import AudioEffect
from m4l_builder.build_fingerprint import device_fingerprint, file_fingerprint
from m4l_builder.paths import device_output_directories, device_output_path


@pytest.mark.parametrize("frozen", [False, True])
def test_fingerprint_tracks_patcher_and_assets(tmp_path, frozen):
    device = AudioEffect("Fresh", 200, 120)
    device.register_asset("code.js", "original")
    path = tmp_path / "Fresh.amxd"
    device.build(str(path), freeze=frozen)
    assert file_fingerprint(path) == device_fingerprint(device)
    # mtime cannot disguise old assets.
    os.utime(path, (2_000_000_000, 2_000_000_000))
    device.register_asset("code.js", "changed by split source or framework")
    assert file_fingerprint(path) != device_fingerprint(device)
    device.register_asset("code.js", "original")
    device.width += 1
    assert file_fingerprint(path) != device_fingerprint(device)


def test_edited_sidecar_is_not_fresh(tmp_path):
    device = AudioEffect("Fresh", 200, 120)
    device.register_asset("code.js", "original")
    path = tmp_path / "Fresh.amxd"
    device.build(str(path))
    (tmp_path / "code.js").write_text("edited")
    assert file_fingerprint(path) != device_fingerprint(device)


def test_path_discovery_includes_midi_tools_without_mkdir(tmp_path, monkeypatch):
    monkeypatch.setenv("M4L_USER_LIBRARY", str(tmp_path))
    assert len(device_output_directories()) == 5
    for kind in ("note_generator", "note_transformation"):
        path = device_output_path("Tool", kind, create_dirs=False)
        assert "MIDI Tools" in path
    assert not list(tmp_path.iterdir())
